import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.iWwp2X7T.js";const _=JSON.parse('{"title":"隐私与边界","description":"Mobile Inspector development documentation · 隐私与边界","frontmatter":{"title":"隐私与边界","description":"Mobile Inspector development documentation · 隐私与边界"},"headers":[],"relativePath":"zh/guide/privacy.md","filePath":"zh/guide/privacy.md"}'),i={name:"zh/guide/privacy.md"};function n(l,a,c,d,h,p){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="隐私与边界" tabindex="-1">隐私与边界 <a class="header-anchor" href="#隐私与边界" aria-label="Permalink to &quot;隐私与边界&quot;">​</a></h1><h2 id="主动采集" tabindex="-1">主动采集 <a class="header-anchor" href="#主动采集" aria-label="Permalink to &quot;主动采集&quot;">​</a></h2><p>SDK、面板与诊断权限只能进入显式内部诊断构建。普通及正式构建应从依赖图排除，不能只在运行时隐藏按钮。记录手动开启、内存有界；配对与采集不触发模型请求。</p><h2 id="保留之前脱敏" tabindex="-1">保留之前脱敏 <a class="header-anchor" href="#保留之前脱敏" aria-label="Permalink to &quot;保留之前脱敏&quot;">​</a></h2><p>凭据、Cookie/认证 Header、签名与配对 token 不进入保留或导出记录。认证路径正文始终排除。即便开启测试正文，二进制文件和音频也只记录大小与状态。URL 查询与片段值移除，可识别标识符转为会话别名。</p><p>脱敏不能识别自由文本中的全部个人内容。主动日志与测试正文仍可能敏感，分享前必须人工复核。导出正文是独立选择；允许采集正文不等于允许 AI 读取全部内容。</p><h2 id="所有权与清除" tabindex="-1">所有权与清除 <a class="header-anchor" href="#所有权与清除" aria-label="Permalink to &quot;所有权与清除&quot;">​</a></h2><p>换号和环境变化必须清除并断开，使旧回调失效。清除会尝试远端清理；接收端不可达时，已有记录可能保留到过期或查看器撤销。关闭 collector 会清空其内存采集，但 TLS 身份与可信项目元数据保留在私有状态目录。主动导出文件由用户另行管理。</p><h2 id="ai-范围" tabindex="-1">AI 范围 <a class="header-anchor" href="#ai-范围" aria-label="Permalink to &quot;AI 范围&quot;">​</a></h2><p>CLI、查看器和 MCP 共用一个 collector 与项目权限。机器默认只读摘要，正文需当前会话授权，禁止类别始终排除。采集文本是不可信证据，不能选择命令、目录、权限或提示词。本站是静态文档，不连接 collector 或模型；教程下载文件全部是合成数据。</p>',10)])])}const u=e(i,[["render",n]]);export{_ as __pageData,u as default};
